CREATE TABLE public.social_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL,target_user_id uuid NOT NULL,recording_id uuid REFERENCES public.voice_recordings(id) ON DELETE SET NULL,reason text NOT NULL CHECK(reason IN ('spam','harassment','inappropriate','impersonation','other')),details text CHECK(length(details)<=1000),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewed','dismissed')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.social_reports TO authenticated; GRANT UPDATE(status) ON public.social_reports TO authenticated; GRANT ALL ON public.social_reports TO service_role;
ALTER TABLE public.social_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_read ON public.social_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.is_admin(auth.uid()));
CREATE POLICY report_create ON public.social_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='open' AND NOT public.is_suspended(auth.uid()) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=target_user_id) AND (recording_id IS NULL OR EXISTS(SELECT 1 FROM public.voice_recordings WHERE id=recording_id AND host_id=target_user_id AND public.can_view_recording(id))));
CREATE POLICY report_review ON public.social_reports FOR UPDATE TO authenticated USING(public.is_admin(auth.uid())) WITH CHECK(public.is_admin(auth.uid()));